const listExistingPageIDsInWorkspace = `-- name: ListExistingPageIDsInWorkspace :many
SELECT id FROM pages
WHERE workspace_id = $1
  AND id IN (
    SELECT value::uuid FROM json_array_elements_text($2::json) AS t(value)
  )
`

type ListExistingPageIDsInWorkspaceParams struct {
	WorkspaceID uuid.UUID
	PageIds     json.RawMessage
}

// 本文に貼られた pageRef 候補のうち、**そのワークスペースに実在するページ** だけを返す
// （リンク切れ・別ワークスペースの ID は黙って除外する。設計 Ⅳ-I）。
func (q *Queries) ListExistingPageIDsInWorkspace(ctx context.Context, arg ListExistingPageIDsInWorkspaceParams) ([]uuid.UUID, error) {
	rows, err := q.db.QueryContext(ctx, listExistingPageIDsInWorkspace, arg.WorkspaceID, arg.PageIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

