const upsertTicketAssignment = `-- name: UpsertTicketAssignment :one

INSERT INTO ticket_assignments
  (workspace_id, ticket_id, assignee_principal_id, assigned_by_user_id, created_at)
VALUES ($1, $2, $3, $4, now())
ON CONFLICT (ticket_id)
DO UPDATE SET assignee_principal_id = EXCLUDED.assignee_principal_id,
              assigned_by_user_id = EXCLUDED.assigned_by_user_id
RETURNING workspace_id, ticket_id, assignee_principal_id, assignee_kind, assigned_by_user_id, created_at
`

type UpsertTicketAssignmentParams struct {
	WorkspaceID         uuid.UUID
	TicketID            uuid.UUID
	AssigneePrincipalID uuid.UUID
	AssignedByUserID    int64
}

// =============================================================================
// ticket_assignments
// =============================================================================
func (q *Queries) UpsertTicketAssignment(ctx context.Context, arg UpsertTicketAssignmentParams) (TicketAssignment, error) {
	row := q.db.QueryRowContext(ctx, upsertTicketAssignment,
		arg.WorkspaceID,
		arg.TicketID,
		arg.AssigneePrincipalID,
		arg.AssignedByUserID,
	)
	var i TicketAssignment
	err := row.Scan(
		&i.WorkspaceID,
		&i.TicketID,
		&i.AssigneePrincipalID,
		&i.AssigneeKind,
		&i.AssignedByUserID,
		&i.CreatedAt,
	)
	return i, err
}
